insert into public.cms_documents(kind,slug,body) values('page','gomulu-sistemler','{"title":"Gömülü Sistemler | İstikbal Aerospace","summary":"PCB tasarımı, elektronik donanım ve gömülü yazılım mühendisliği.","paragraphs":[],"date":null,"source":null,"stage":null,"fields":{"focus.embedded.title":"Gömülü Sistemler","focus.embedded.tagline":"Donanımla yazılımın birlikte düşünüldüğü sistemler.","focus.embedded.bg":"platform-systems.svg","focus.embedded.kicker":"DONANIM & YAZILIM / 02","FocusContent.text.0":"TEKNOLOJİYE YAKINDAN BAKIŞ","FocusContent.text.1":"Bir disiplinin farklı katmanları.","focus.embedded.intro":"Gömülü sistem geliştirme; işlem birimi, çevre birimleri, yazılım ve haberleşme arayüzlerinin birlikte ele alınmasını gerektirir. Buradaki başlıklar teknik yaklaşımın genel bir açıklamasıdır.","FocusContent.kicker.2":"TEMEL YAKLAŞIM","FocusContent.title.3":"Mühendislik bileşenleri.","FocusContent.lead.4":"Konuya ait kavramlar ve çalışma ilkeleri; doğrulanmış proje bilgileri ayrıca yayınlanacaktır.","focus.embedded.modules.0.1":"Elektronik mimari","focus.embedded.modules.0.2":"Elektronik bileşenlerin işlevsel bir sistem içinde düzenlenmesine dair temel yaklaşım.","focus.embedded.modules.1.1":"Gömülü yazılım","focus.embedded.modules.1.2":"Donanım kaynaklarını yöneten ve sistem davranışını tanımlayan yazılım katmanı.","focus.embedded.modules.2.1":"Entegrasyon ve test","focus.embedded.modules.2.2":"Donanım ve yazılımın birlikte değerlendirilmesi, arayüzlerin doğrulanması.","FocusContent.text.5":"Sistemler birlikte çalışır: ","FocusContent.text.6":" ile ","focus.embedded.related":"Sensör Füzyonu","FocusContent.text.7":" birbirini tamamlayan mühendislik alanlarıdır. Teknoloji başlıkları birbirinden bağımsız değildir."}}'::jsonb) on conflict(kind,slug) do update set body=excluded.body where cms_documents.revision=1 and not(cms_documents.body ? 'fields');
insert into public.cms_documents(kind,slug,body) values('page','haber-detay','{"title":"Tengri AI Paylaşımı | İstikbal Aerospace","summary":"Tengri AI ve bağlantılı savunma ağları konusunda kamuya açık şirket tanıtımı.","paragraphs":[],"date":null,"source":null,"stage":null,"fields":{"news.sourceUrl":"https://tr.linkedin.com/posts/i%CC%87stikbal-aerospace_tengriai-defenseai-savunmasanayi-activity-7370532002627878912-WIXo","news.article.heroTitle":"Tengri AI","news.article.heroDescription":"Yapay zekâ destekli savunma ağı yaklaşımı üzerine şirket paylaşımı.","news.image":"tengri-network.svg","news.article.breadcrumb":"HABERLER / TENGRİ AI","news.article.eyebrow":"ŞİRKETİN KAMUYA AÇIK PAYLAŞIMI","news.article.heading":"Tengri AI ve bağlantılı savunma sistemleri.","news.article.intro":"İstikbal Aerospace, Tengri AI tanıtımında çok katmanlı yapay zekâ, tehdit değerlendirme, hava ve kara sistemleri arasında koordinasyon ve ağ tabanlı karar desteği hedeflerini paylaştı.","news.article.sectionHeading":"Teknoloji vizyonu","news.article.sectionBody":"Sensör verilerinin bir araya getirilmesi, çoklu hedeflerin değerlendirilmesi ve bilgi paylaşımı, tanıtımda öne çıkan ana başlıklardır. Açıklanan konseptler doğrulanmış operasyonel performans bilgisi olarak sunulmamaktadır.","NewsDetailContent.text.8":"Orijinal LinkedIn paylaşımı ↗"}}'::jsonb) on conflict(kind,slug) do update set body=excluded.body where cms_documents.revision=1 and not(cms_documents.body ? 'fields');
