insert into public.cms_documents(kind,slug,body) values('page','index','{"title":"Ana Sayfa | İstikbal Aerospace","summary":"İstikbal Aerospace havacılık, otonom sistemler, gömülü elektronik ve mühendislik alanları.","paragraphs":[],"date":null,"source":null,"stage":null,"fields":{"HomeContent.text.0":"SİSTEM MÜHENDİSLİĞİ","HomeContent.text.1":"Gömülü elektronik.","HomeContent.text.2":"Otonom hareket.","HomeContent.text.3":"Entegre sistemler.","HomeContent.text.4":"DONANIM","HomeContent.text.5":"YAZILIM","HomeContent.text.6":"SİSTEM ENTEGRASYONU","HomeContent.text.7":"Birbiriyle çalışan teknolojiler.","HomeContent.text.8":"İstikbal Aerospace; insansız hava araçları, PCB tasarımı, gömülü sistemler ve otonom algoritmalar çevresinde şekillenen mühendislik alanlarına odaklanıyor. Sensörlerden elde edilen verinin işlenmesinden sistem düzeyinde entegrasyona kadar uzanan bir teknoloji yaklaşımı.","HomeContent.kicker.9":"01 / HAVA & SİSTEMLER","HomeContent.title.10":"Havacılığın farklı katmanları.","HomeContent.lead.11":"İnsansız hava platformlarından uçuş elektroniğine, bağlantılı sistem mimarilerinden otonom çözümlere uzanan çalışma alanları.","cards.platform.0.title":"İnsansız Hava Sistemleri","cards.platform.0.image":"hero-hangar-photo.webp","cards.platform.0.href":"iha-sistemleri.html","cards.platform.0.description":"İnsansız platform mimarileri ve hava aracı sistemleri.","cards.platform.1.title":"Gömülü Uçuş Mimarileri","cards.platform.1.image":"platform-systems.svg","cards.platform.1.href":"ucus-mimarileri.html","cards.platform.1.description":"Donanım, yazılım ve kontrol katmanları.","cards.platform.2.title":"Hava Savunma Ağları","cards.platform.2.image":"platform-flight.svg","cards.platform.2.href":"hava-savunma-aglari.html","cards.platform.2.description":"Birbirine bağlı savunma sistemleri yaklaşımı.","HomeContent.kicker.12":"02 / TEKNOLOJİLER","HomeContent.title.13":"Sistemin ardındaki mühendislik.","HomeContent.lead.14":"Elektronik tasarımdan verinin birleştirilmesine uzanan temel çalışma alanları.","cards.technology.0.title":"Otonom Sistemler","cards.technology.0.description":"Algılama, karar süreçleri ve kontrol algoritmaları.","cards.technology.0.href":"otonom-sistemler.html","cards.technology.1.title":"Gömülü Sistemler & PCB","cards.technology.1.description":"Elektronik kart tasarımı, donanım ve gömülü yazılım.","cards.technology.1.href":"gomulu-sistemler.html","cards.technology.2.title":"Sensör Füzyonu","cards.technology.2.description":"Farklı algılayıcılardan gelen verilerin bütünleştirilmesi.","cards.technology.2.href":"sensor-fuzyonu.html","cards.technology.3.title":"Yapay Zekâ & Tengri AI","cards.technology.3.description":"Ağ tabanlı karar destek ve savunma teknolojileri yaklaşımı.","cards.technology.3.href":"tengri-ai.html","HomeContent.text.15":"03 / YAPAY ZEKÂ VE KOMUTA KONTROL","HomeContent.text.16":"TENGRİ AI","HomeContent.text.17":"Hava ve kara sistemlerinin koordinasyonuna yönelik yapay zekâ temelli savunma ağı yaklaşımı. Algılama, tehdit değerlendirme ve karar destek katmanları üzerine çalışmalar.","HomeContent.text.18":"YAPAY ZEKÂ · AĞ MİMARİLERİ · KARAR DESTEK","HomeContent.href.19":"tengri-ai.html","HomeContent.text.20":"Tengri AI","HomeContent.kicker.21":"04 / PROJELER & AR-GE","HomeContent.title.22":"Araştırmadan uygulamaya.","HomeContent.lead.23":"PCB tasarımı, otonom hareket mühendisliği ve gömülü donanım gibi alanlarda araştırma ve geliştirme yaklaşımı.","HomeContent.image.24":"research-lab.svg","HomeContent.text.25":"AR-GE & ELEKTRONİK","HomeContent.text.26":"Sistemler, detaylarda şekillenir.","HomeContent.text.27":"Elektronik donanım, gömülü yazılım ve otonom kontrolün birbirini tamamlayan disiplinler olarak ele alındığı mühendislik alanları.","HomeContent.kicker.28":"05 / HABERLER & DUYURULAR","HomeContent.title.29":"Kamuya açık gelişmeler.","HomeContent.lead.30":"Şirketin paylaştığı teknoloji çalışmalarına ve duyurularına göz atın.","HomeContent.image.31":"tengri-network.svg","HomeContent.text.32":"ŞİRKET PAYLAŞIMI / TENGRİ AI","HomeContent.text.33":"Tengri AI: Yapay zekâ destekli savunma ağı yaklaşımı","HomeContent.text.34":"İstikbal Aerospace tarafından kamuya açık olarak tanıtılan Tengri AI''ın odaklandığı teknoloji alanlarını keşfedin.","HomeContent.href.35":"haber-detay.html","HomeContent.text.36":"Gelişmeyi İncele","HomeContent.image.37":"hero-hangar-photo.webp","HomeContent.text.38":"06 / İSTİKBAL AEROSPACE","HomeContent.text.39":"Antalya''dan geleceğin teknolojilerine.","HomeContent.text.40":"Antalya merkezli İstikbal Aerospace; havacılık, gömülü elektronik, PCB tasarımı ve otonom sistem mühendisliğini bir araya getiren çalışmalar yürütür.","Hero.aria-label.0":"İstikbal Aerospace havacılık vitrini","Hero.aria-label.1":"Gün doğumunda dağların üzerinde uçan markasız temsili hava aracı","Hero.aria-label.2":"Alacakaranlıkta havacılık hangarındaki markasız temsili hava aracı","Hero.text.3":" HAVACILIK ","Hero.text.4":" OTONOM SİSTEMLER","Hero.text.5":"Geleceğin","Hero.text.6":"sistemlerini","Hero.text.7":"tasarlıyoruz.","Hero.text.8":"Havacılık, gömülü elektronik ve otonom sistemlerin kesişiminde mühendislik.","Hero.href.9":"platformlar.html","Hero.text.10":"Platformları Keşfet ","Hero.href.11":"iletisim.html","Hero.text.12":"İletişime Geç "}}'::jsonb) on conflict(kind,slug) do update set body=excluded.body where cms_documents.revision=1 and not(cms_documents.body ? 'fields');
insert into public.cms_documents(kind,slug,body) values('page','kabiliyetler','{"title":"Kabiliyetler | İstikbal Aerospace","summary":"İstikbal Aerospace''in kamuya açık mühendislik uzmanlık ve teknoloji alanları.","paragraphs":[],"date":null,"source":null,"stage":null,"fields":{"CapabilitiesContent.title.0":"Kabiliyetler","CapabilitiesContent.description.1":"İnsansız sistemlerden gömülü elektroniğe uzanan mühendislik çalışma alanları.","CapabilitiesContent.image.2":"research-lab.svg","CapabilitiesContent.breadcrumb.3":"TEKNOLOJİLER / KABİLİYETLER","CapabilitiesContent.kicker.4":"İSTİKBAL AEROSPACE","CapabilitiesContent.kicker.5":"MÜHENDİSLİK & TEKNOLOJİ ALANLARI","CapabilitiesContent.title.6":"Sistemlerin yapı taşları.","CapabilitiesContent.lead.7":"İstikbal Aerospace’in kamuya açık faaliyet ve uzmanlık tanıtımlarında yer alan başlıklar: insansız hava sistemleri, roket sistemleri, hava savunma ağları, haberleşme, gömülü donanım ve algılama.","cards.technology.4.title":"İnsansız Hava Araçları","cards.technology.4.description":"Hava platformları ve otonom uçuş mimarileri.","cards.technology.4.href":"iha-sistemleri.html","cards.technology.5.title":"Hava Savunma Ağları","cards.technology.5.description":"Ağ bağlantılı hava savunma ve karar destek yaklaşımı.","cards.technology.5.href":"hava-savunma-aglari.html","cards.technology.6.title":"İleri Haberleşme","cards.technology.6.description":"Bağlantılı platformlar ve taktik veri iletimi odağı.","cards.technology.6.href":"ileri-haberlesme.html","cards.technology.7.title":"Roket Sistemleri","cards.technology.7.description":"Roket projelerinde uçuş elektroniği ve sistem entegrasyonu hakkında genel mühendislik çerçevesi.","cards.technology.7.href":"roket-sistemleri.html","cards.technology.8.title":"Gömülü Donanım & PCB","cards.technology.8.description":"Elektronik kart tasarımı ve donanım-yazılım bütünlüğü.","cards.technology.8.href":"gomulu-sistemler.html","cards.technology.9.title":"Sensör Füzyonu","cards.technology.9.description":"Birden fazla veri kaynağının birlikte değerlendirilmesi.","cards.technology.9.href":"sensor-fuzyonu.html","CapabilitiesContent.title.8":"Otonom Sistemler","CapabilitiesContent.kicker.9":"OTONOMİ","CapabilitiesContent.description.10":"Veri analizi, kontrol mantığı ve karar mekanizmalarının bir arada ele alındığı sistemler.","CapabilitiesContent.image.11":"platform-flight.svg","CapabilitiesContent.title.12":"Gömülü Donanım & PCB","CapabilitiesContent.kicker.13":"ELEKTRONİK","CapabilitiesContent.description.14":"Elektronik kart tasarımı, gömülü işlemciler ve donanım-yazılım entegrasyonu.","CapabilitiesContent.image.15":"platform-systems.svg","CapabilitiesContent.title.16":"Sensör Füzyonu","CapabilitiesContent.kicker.17":"ALGILAMA","CapabilitiesContent.description.18":"Farklı sensör verilerinin işlenmesi ve tek bir sistem görünümüne dönüştürülmesi.","CapabilitiesContent.image.19":"tengri-network.svg","CapabilitiesContent.kicker.20":"YAPAY ZEKÂ","CapabilitiesContent.title.21":"Tengri AI.","CapabilitiesContent.lead.22":"Şirketin yapay zekâ ve ağ merkezli karar desteği üzerine kamuya açık teknoloji yaklaşımı, diğer mühendislik disiplinleriyle ilişkilidir."}}'::jsonb) on conflict(kind,slug) do update set body=excluded.body where cms_documents.revision=1 and not(cms_documents.body ? 'fields');
insert into public.cms_documents(kind,slug,body) values('page','kurumsal','{"title":"Kurumsal | İstikbal Aerospace","summary":"İstikbal Aerospace mühendislik yaklaşımı, prototipleme ve sistem entegrasyonu.","paragraphs":[],"date":null,"source":null,"stage":null,"fields":{"AboutContent.title.0":"Kurumsal","AboutContent.description.1":"Havacılık, gömülü sistemler ve otonom yazılım odağında disiplinler arası mühendislik.","AboutContent.image.2":"hero-hangar-photo.webp","AboutContent.breadcrumb.3":"KURUMSAL","AboutContent.kicker.4":"İSTİKBAL AEROSPACE","AboutContent.kicker.5":"HAKKIMIZDA","AboutContent.title.6":"Fikirden çalışan sisteme.","AboutContent.lead.7":"İstikbal Aerospace, Antalya / Kepez merkezli; havacılık, uzay ve savunma teknolojilerine yönelik alt sistemler, gömülü elektronik ve otonom yazılım çalışmalarına odaklanan bir teknoloji ve AR-GE girişimidir.","AboutContent.image.8":"research-lab.svg","AboutContent.text.9":"MÜHENDİSLİK YAKLAŞIMI","AboutContent.text.10":"Donanım, yazılım ve otonomi bir arada.","AboutContent.text.11":"Elektronik tasarım, gömülü uçuş mimarileri ve otonom algoritmalar birbirinden bağımsız parçalar değildir. İstikbal Aerospace, kamuya açık kurumsal tanıtımında bu disiplinleri birlikte ele alan, çevik ve prototip geliştirmeye odaklı bir mühendislik yaklaşımı benimsediğini ifade eder.","AboutContent.text.12":"Yaklaşımın odağında, kavramsal tasarımların donanım ve yazılımla buluşturulması; alt sistemlerin birlikte çalışabilir, incelenebilir ve test edilebilir yapılar olarak değerlendirilmesi bulunur.","AboutContent.kicker.13":"ÇALIŞMA YAKLAŞIMI","AboutContent.title.14":"Tasarım. Prototipleme. Entegrasyon.","AboutContent.lead.15":"İstikbal Aerospace’in kamuya açık tanıtımında öne çıkan mühendislik süreçleri.","AboutContent.title.16":"Sistem Tasarımı","AboutContent.description.17":"Elektronik donanım, uçuş mimarileri ve yazılım bileşenlerini ortak bir sistem çerçevesinde değerlendirme.","AboutContent.title.18":"Hızlı Prototipleme","AboutContent.description.19":"Kavramsal fikirlerin elektronik tasarım, gömülü yazılım ve algoritma geliştirmeyle somutlaştırılması.","AboutContent.title.20":"Entegrasyon","AboutContent.description.21":"Farklı bileşenler arasında veri akışı, kontrol ve sistem davranışının bütün olarak ele alınması.","AboutContent.kicker.22":"FAALİYET ALANLARI","AboutContent.title.23":"Birbirini tamamlayan mühendislik alanları.","AboutContent.lead.24":"Şirketin kamuya açık tanıtımlarında yer alan çalışma başlıklarını ilgili sayfalardan inceleyebilirsiniz.","cards.technology.10.title":"Gömülü Uçuş Sistemleri","cards.technology.10.description":"Hava araçları için donanım ve yazılım mimarilerinin tasarımı.","cards.technology.10.href":"ucus-mimarileri.html","cards.technology.11.title":"Otonom Algoritmalar","cards.technology.11.description":"Algılama, karar mekanizmaları ve otonom sistemlerin mühendislik temelleri.","cards.technology.11.href":"otonom-sistemler.html","cards.technology.12.title":"Yapay Zekâ & Sistemler","cards.technology.12.description":"Tengri AI çevresinde ele alınan yapay zekâ destekli savunma ağı konseptleri.","cards.technology.12.href":"tengri-ai.html","AboutContent.text.25":"KONUM","AboutContent.text.26":"Kepez, Antalya.","AboutContent.text.27":"İstikbal Aerospace’in kamuya açık şirket profilinde merkez konumu Kepez / Antalya olarak belirtilmektedir. İş birliği ve iletişim talepleri için iletişim sayfamıza ulaşabilirsiniz."}}'::jsonb) on conflict(kind,slug) do update set body=excluded.body where cms_documents.revision=1 and not(cms_documents.body ? 'fields');
insert into public.cms_documents(kind,slug,body) values('page','otonom-sistemler','{"title":"Otonom Sistemler | İstikbal Aerospace","summary":"Algılama, karar mekanizmaları ve kontrol sistemlerine genel bakış.","paragraphs":[],"date":null,"source":null,"stage":null,"fields":{"focus.autonomy.title":"Otonom Sistemler","focus.autonomy.tagline":"Algılama, karar verme ve kontrolün buluştuğu alan.","focus.autonomy.bg":"platform-flight.svg","focus.autonomy.kicker":"SİSTEM MÜHENDİSLİĞİ / 01","FocusContent.text.0":"TEKNOLOJİYE YAKINDAN BAKIŞ","FocusContent.text.1":"Bir disiplinin farklı katmanları.","focus.autonomy.intro":"Otonom sistemler; çevreyi algılama, veriyi yorumlama ve belirlenen hedeflere göre hareket üretme gibi farklı mühendislik disiplinlerini bir araya getirir. Bu sayfa, konunun genel yaklaşımını tanıtır.","FocusContent.kicker.2":"TEMEL YAKLAŞIM","FocusContent.title.3":"Mühendislik bileşenleri.","FocusContent.lead.4":"Konuya ait kavramlar ve çalışma ilkeleri; doğrulanmış proje bilgileri ayrıca yayınlanacaktır.","focus.autonomy.modules.0.1":"Algılama ve veri","focus.autonomy.modules.0.2":"Sensörlerden gelen verilerin sistem tarafından yorumlanmasına yönelik mühendislik yaklaşımı.","focus.autonomy.modules.1.1":"Karar mekanizmaları","focus.autonomy.modules.1.2":"Algılanan duruma göre kuralların ve algoritmaların rolünü açıklayan genel çerçeve.","focus.autonomy.modules.2.1":"Kontrol ve geri bildirim","focus.autonomy.modules.2.2":"Ölçüm, kontrol ve geri bildirim döngülerinin sistem tasarımındaki yeri.","FocusContent.text.5":"Sistemler birlikte çalışır: ","FocusContent.text.6":" ile ","focus.autonomy.related":"Gömülü Sistemler","FocusContent.text.7":" birbirini tamamlayan mühendislik alanlarıdır. Teknoloji başlıkları birbirinden bağımsız değildir."}}'::jsonb) on conflict(kind,slug) do update set body=excluded.body where cms_documents.revision=1 and not(cms_documents.body ? 'fields');
insert into public.cms_documents(kind,slug,body) values('page','platform-detay','{"title":"Platform Detayı | İstikbal Aerospace","summary":"Havacılık platformları, uçuş elektroniği ve sistem entegrasyonunun temelleri.","paragraphs":[],"date":null,"source":null,"stage":null,"fields":{"PlatformDetailContent.title.0":"Havacılık Sistemleri","PlatformDetailContent.description.1":"Platform mühendisliği, uçuş elektroniği ve sistem entegrasyonu.","PlatformDetailContent.image.2":"platform-flight.svg","PlatformDetailContent.breadcrumb.3":"HAVACILIK SISTEMLERI","PlatformDetailContent.kicker.4":"İSTİKBAL AEROSPACE","PlatformDetailContent.title.5":"Mühendislik disiplinleri.","PlatformDetailContent.kicker.6":"SİSTEM ALANLARI","PlatformDetailContent.description.7":"İstikbal Aerospace’in gömülü donanım, otonom sistemler ve mühendislik çalışma alanları birlikte ele alınır.","PlatformDetailContent.image.8":"platform-flight.svg"}}'::jsonb) on conflict(kind,slug) do update set body=excluded.body where cms_documents.revision=1 and not(cms_documents.body ? 'fields');
insert into public.cms_documents(kind,slug,body) values('page','platformlar','{"title":"Platformlar | İstikbal Aerospace","summary":"İnsansız hava sistemleri, gömülü uçuş mimarileri ve hava savunma sistemleri çalışma alanları.","paragraphs":[],"date":null,"source":null,"stage":null,"fields":{"PlatformsContent.title.0":"Platformlar","PlatformsContent.description.1":"Hava platformları, uçuş kontrolü ve sistem mühendisliği odağındaki çalışma başlıkları.","PlatformsContent.image.2":"hero-hangar-photo.webp","PlatformsContent.breadcrumb.3":"PLATFORMLAR","PlatformsContent.kicker.4":"İSTİKBAL AEROSPACE","PlatformsContent.kicker.5":"HAVACILIK & SİSTEMLER","PlatformsContent.title.6":"Platformdan alt sisteme.","PlatformsContent.lead.7":"İstikbal Aerospace’in kamuya açık uzmanlık alanlarından hareketle sunulan sistem aileleri. Bu başlıklar bir ürün kataloğu değil, mühendislik alanlarıdır.","cards.platform.3.title":"İnsansız Hava Sistemleri","cards.platform.3.image":"hero-hangar-photo.webp","cards.platform.3.href":"iha-sistemleri.html","cards.platform.3.description":"Uçuş kontrolü, algılama ve bağlantılı alt sistemlerin bütünleşik mimarisi.","cards.platform.4.title":"Gömülü Uçuş Mimarileri","cards.platform.4.image":"platform-systems.svg","cards.platform.4.href":"ucus-mimarileri.html","cards.platform.4.description":"Uçuş elektroniği, gömülü yazılım ve platform kontrolünün bileşenleri.","cards.platform.5.title":"Hava Savunma Ağları","cards.platform.5.image":"platform-flight.svg","cards.platform.5.href":"hava-savunma-aglari.html","cards.platform.5.description":"Bağlantılı sistemler ve karar destek teknolojileri yaklaşımı.","PlatformsContent.title.8":"Yapay zekâ destekli uçuş kontrolü.","PlatformsContent.kicker.9":"KAMUYA AÇIK TEKNOLOJİ TANITIMI","PlatformsContent.description.10":"Şirketin paylaştığı yeni nesil uçuş kontrolcüsü tanıtımında yapay zekâ ile ilişkili kontrol algoritmaları, uçuş güvenliği ve verimlilik hedefleri öne çıkıyor. Teknolojinin mühendislik temellerini inceleyin.","PlatformsContent.image.11":"platform-systems.svg","PlatformsContent.href.12":"ucus-kontrol-paylasimi.html","PlatformsContent.label.13":"Tanıtımı İncele","PlatformsContent.kicker.14":"İLGİLİ TEKNOLOJİLER","PlatformsContent.title.15":"Bir platformun ötesindeki sistemler.","PlatformsContent.lead.16":"Elektronik tasarım, yazılım ve sensör verisinin birlikte değerlendirilmesi platform mühendisliğinin temelindedir.","cards.technology.13.title":"Otonom Sistemler","cards.technology.13.description":"Algılama ve kontrolün birleştiği yazılım alanı.","cards.technology.13.href":"otonom-sistemler.html","cards.technology.14.title":"Gömülü Sistemler","cards.technology.14.description":"Uçuş elektroniği ve sistem denetimi.","cards.technology.14.href":"gomulu-sistemler.html","cards.technology.15.title":"Sensör Füzyonu","cards.technology.15.description":"Çoklu veri kaynağının birlikte değerlendirilmesi.","cards.technology.15.href":"sensor-fuzyonu.html"}}'::jsonb) on conflict(kind,slug) do update set body=excluded.body where cms_documents.revision=1 and not(cms_documents.body ? 'fields');
