insert into public.cms_documents(kind,slug,body) values('page','projeler','{"title":"Projeler & AR-GE | İstikbal Aerospace","summary":"İstikbal Aerospace kamuya açık teknoloji paylaşımları ve AR-GE çalışma alanları.","paragraphs":[],"date":null,"source":null,"stage":null,"fields":{"ProjectsContent.title.0":"Projeler & AR-GE","ProjectsContent.description.1":"Kamuya açık teknoloji tanıtımları ve mühendislik çalışma alanları.","ProjectsContent.image.2":"research-lab.svg","ProjectsContent.breadcrumb.3":"PROJELER & AR-GE","ProjectsContent.kicker.4":"İSTİKBAL AEROSPACE","ProjectsContent.kicker.5":"KAMUYA AÇIK ÇALIŞMALAR","ProjectsContent.title.6":"Teknoloji fikirlerinden paylaşılan çalışmalara.","ProjectsContent.lead.7":"İstikbal Aerospace’in kamuya açık tanıtımlarında yer alan çalışmalar. Geliştirme ve test aşamalarına ilişkin ayrıntılar şirket onayına bağlıdır.","publicWorks.0.title":"Tengri AI — Yapay zekâ ve savunma ağı konsepti","publicWorks.0.summary":"Bağlantılı hava ve kara sistemleri arasında durumsal farkındalık ve karar desteği vizyonu.","publicWorks.0.image":"tengri-network.svg","publicWorks.0.href":"tengri-ai.html","publicWorks.1.title":"Yeni nesil uçuş kontrolcüsü tanıtımı","publicWorks.1.summary":"Yapay zekâ destekli kontrol algoritmalarını ve uçuş sistemlerini bir araya getirmeyi hedefleyen teknoloji paylaşımı.","publicWorks.1.image":"platform-systems.svg","publicWorks.1.href":"ucus-kontrol-paylasimi.html","ProjectsContent.kicker.8":"AR-GE DİSİPLİNLERİ","ProjectsContent.title.9":"Elektronikten sisteme.","ProjectsContent.lead.10":"Kurumsal faaliyet tanıtımında yer alan çalışma alanları; bunlar tek başına tamamlanmış projeler olarak listelenmemektedir.","cards.technology.16.title":"PCB Tasarımı","cards.technology.16.description":"Gömülü donanım için elektronik kart mimarileri.","cards.technology.16.href":"gomulu-sistemler.html","cards.technology.17.title":"Otonom Hareket","cards.technology.17.description":"Karar, kontrol ve geri bildirim mekanizmaları.","cards.technology.17.href":"otonom-sistemler.html","cards.technology.18.title":"Algılama & Veri","cards.technology.18.description":"Sensör bilgisi ve sistem entegrasyonu.","cards.technology.18.href":"sensor-fuzyonu.html","ProjectsContent.kicker.11":"MÜHENDİSLİK YAKLAŞIMI","ProjectsContent.title.12":"Araştırma, uygulama, bütünleştirme.","ProjectsContent.lead.13":"Fikirlerin donanım ve yazılımla buluştuğu sistem geliştirme adımları. PCB tasarımı ve gömülü yazılımın uçuş elektroniğiyle kurduğu ilişki bütünleşik sistem yaklaşımının parçasıdır.","ProjectsContent.text.14":"İhtiyaç Analizi","ProjectsContent.text.15":"Görev ve sistem gereksinimlerinin belirlenmesi.","ProjectsContent.text.16":"Elektronik Tasarım","ProjectsContent.text.17":"Donanım ve arayüzlerin tasarlanması.","ProjectsContent.text.18":"Yazılım & Kontrol","ProjectsContent.text.19":"Gömülü yazılım ve kontrol algoritmalarının geliştirilmesi.","ProjectsContent.text.20":"Sistem Entegrasyonu","ProjectsContent.text.21":"Alt sistemlerin birlikte değerlendirilmesi."}}'::jsonb) on conflict(kind,slug) do update set body=excluded.body where cms_documents.revision=1 and not(cms_documents.body ? 'fields');
insert into public.cms_documents(kind,slug,body) values('page','roket-sistemleri','{"title":"Roket Sistemleri | İstikbal Aerospace","summary":"Roket teknolojileriyle ilişkili uçuş elektroniği, telemetri ve sistem mühendisliği.","paragraphs":[],"date":null,"source":null,"stage":null,"fields":{"focus.rockets.title":"Roket Sistemleri","focus.rockets.tagline":"Uçuş elektroniği, telemetri ve sistem bütünlüğü.","focus.rockets.bg":"platform-flight.svg","focus.rockets.kicker":"HAVACILIK & UZAY / 04","FocusContent.text.0":"TEKNOLOJİYE YAKINDAN BAKIŞ","FocusContent.text.1":"Bir disiplinin farklı katmanları.","focus.rockets.intro":"Roket sistemleri, İstikbal Aerospace’in kamuya açık uzmanlık alanları listesinde geçmektedir. Bu sayfa roket projelerinde ele alınan genel mühendislik disiplinlerini tanıtır; şirkete ait belirli bir ürün, uçuş testi veya performans iddiası içermez.","FocusContent.kicker.2":"TEMEL YAKLAŞIM","FocusContent.title.3":"Mühendislik bileşenleri.","FocusContent.lead.4":"Konuya ait kavramlar ve çalışma ilkeleri; doğrulanmış proje bilgileri ayrıca yayınlanacaktır.","focus.rockets.modules.0.1":"Uçuş elektroniği","focus.rockets.modules.0.2":"Algılama, kontrol ve uçuş bilgisinin değerlendirilmesinde elektronik bileşenlerin genel rolü.","focus.rockets.modules.1.1":"Telemetri ve haberleşme","focus.rockets.modules.1.2":"Sistem verilerinin izlenmesi ve bağlantılı birimlerle bilgi alışverişi.","focus.rockets.modules.2.1":"Entegrasyon ve doğrulama","focus.rockets.modules.2.2":"Elektronik, yazılım ve mekanik alt sistemlerin bütün halinde ele alınması.","FocusContent.text.5":"Sistemler birlikte çalışır: ","FocusContent.text.6":" ile ","focus.rockets.related":"Gömülü Uçuş Mimarileri","FocusContent.text.7":" birbirini tamamlayan mühendislik alanlarıdır. Teknoloji başlıkları birbirinden bağımsız değildir."}}'::jsonb) on conflict(kind,slug) do update set body=excluded.body where cms_documents.revision=1 and not(cms_documents.body ? 'fields');
insert into public.cms_documents(kind,slug,body) values('page','sensor-fuzyonu','{"title":"Sensör Füzyonu | İstikbal Aerospace","summary":"Farklı algılayıcılardan gelen verilerin birlikte değerlendirilmesi.","paragraphs":[],"date":null,"source":null,"stage":null,"fields":{"focus.sensors.title":"Sensör Füzyonu","focus.sensors.tagline":"Birden fazla veri kaynağından daha tutarlı bir tablo.","focus.sensors.bg":"tengri-network.svg","focus.sensors.kicker":"ALGILAMA & ENTEGRASYON / 03","FocusContent.text.0":"TEKNOLOJİYE YAKINDAN BAKIŞ","FocusContent.text.1":"Bir disiplinin farklı katmanları.","focus.sensors.intro":"Sensör füzyonu, farklı algılayıcılardan elde edilen bilgilerin değerlendirilerek birlikte kullanılmasına yönelik mühendislik alanıdır. Açıklamalar genel teknoloji tanıtımıdır; şirkete özgü performans iddiası içermez.","FocusContent.kicker.2":"TEMEL YAKLAŞIM","FocusContent.title.3":"Mühendislik bileşenleri.","FocusContent.lead.4":"Konuya ait kavramlar ve çalışma ilkeleri; doğrulanmış proje bilgileri ayrıca yayınlanacaktır.","focus.sensors.modules.0.1":"Veri kaynakları","focus.sensors.modules.0.2":"Farklı ölçümlerin nitelikleri, zamanlaması ve kullanılabilirliği.","focus.sensors.modules.1.1":"Birleştirme yaklaşımı","focus.sensors.modules.1.2":"Farklı kaynaklardan gelen bilgilerin karşılaştırılması ve birlikte ele alınması.","focus.sensors.modules.2.1":"Sistem ilişkileri","focus.sensors.modules.2.2":"Algılama katmanının otonomi ve gömülü sistemlerle bağlantısı.","FocusContent.text.5":"Sistemler birlikte çalışır: ","FocusContent.text.6":" ile ","focus.sensors.related":"Otonom Sistemler","FocusContent.text.7":" birbirini tamamlayan mühendislik alanlarıdır. Teknoloji başlıkları birbirinden bağımsız değildir."}}'::jsonb) on conflict(kind,slug) do update set body=excluded.body where cms_documents.revision=1 and not(cms_documents.body ? 'fields');
insert into public.cms_documents(kind,slug,body) values('page','teknolojiler','{"title":"Teknolojiler | İstikbal Aerospace","summary":"Gömülü sistemler, yapay zekâ, otonomi, sensör füzyonu, roket sistemleri ve haberleşme.","paragraphs":[],"date":null,"source":null,"stage":null,"fields":{"TechContent.title.0":"Teknolojiler","TechContent.description.1":"Donanım, kontrol, algılama ve yapay zekâ tabanlı sistemlerin buluştuğu mühendislik alanları.","TechContent.image.2":"platform-systems.svg","TechContent.breadcrumb.3":"TEKNOLOJILER","TechContent.kicker.4":"İSTİKBAL AEROSPACE","TechContent.kicker.5":"TEKNOLOJİ ALANLARI","TechContent.title.6":"Donanımdan otonomiye.","TechContent.lead.7":"Elektronik tasarım, gömülü yazılım, sensör füzyonu ve sistem entegrasyonu birbirini tamamlayan disiplinlerdir. Teknoloji alanları, sistemlerin alt katmanlarını birlikte ele alır.","cards.technology.19.title":"Otonom Sistemler","cards.technology.19.description":"Sensör verilerinin değerlendirilmesi, karar ve kontrol algoritmaları.","cards.technology.19.href":"otonom-sistemler.html","cards.technology.20.title":"Gömülü Donanım & PCB","cards.technology.20.description":"Elektronik kart tasarımı, işlemci tabanlı sistemler ve gömülü yazılım.","cards.technology.20.href":"gomulu-sistemler.html","cards.technology.21.title":"Sensör Füzyonu","cards.technology.21.description":"Birden fazla algılayıcıdan gelen bilginin birlikte işlenmesi.","cards.technology.21.href":"sensor-fuzyonu.html","cards.technology.22.title":"Yapay Zekâ / Tengri AI","cards.technology.22.description":"Karar destek ve bağlantılı savunma ağlarına odaklanan teknoloji yaklaşımı.","cards.technology.22.href":"tengri-ai.html","cards.technology.23.title":"Roket Sistemleri","cards.technology.23.description":"Roket teknolojileriyle ilişkili uçuş elektroniği, telemetri ve sistem mühendisliğine genel bakış.","cards.technology.23.href":"roket-sistemleri.html","cards.technology.24.title":"İleri Haberleşme","cards.technology.24.description":"Bağlantılı platformlarda veri iletimi, güvenli haberleşme ve sistem entegrasyonu.","cards.technology.24.href":"ileri-haberlesme.html","TechContent.image.8":"tengri-network.svg","TechContent.text.9":"YAPAY ZEKÂ / TENGRİ AI","TechContent.text.10":"Ağ bağlantılı karar destek.","TechContent.text.11":"Tengri AI, şirketin kamuya açık tanıtımında bağlı hava ve kara sistemlerinin koordinasyonunu hedefleyen yapay zekâ yaklaşımı olarak anlatılıyor."}}'::jsonb) on conflict(kind,slug) do update set body=excluded.body where cms_documents.revision=1 and not(cms_documents.body ? 'fields');
insert into public.cms_documents(kind,slug,body) values('page','tengri-ai','{"title":"Tengri AI | İstikbal Aerospace","summary":"Tengri AI yapay zekâ, durumsal farkındalık ve karar destek teknoloji vizyonu.","paragraphs":[],"date":null,"source":null,"stage":null,"fields":{"TengriContent.title.0":"TENGRİ AI","TengriContent.description.1":"Çok katmanlı yapay zekâ, durumsal farkındalık ve bağlantılı savunma sistemleri vizyonu.","TengriContent.image.2":"tengri-network.svg","TengriContent.breadcrumb.3":"TEKNOLOJİLER / TENGRİ AI","TengriContent.kicker.4":"YAPAY ZEKÂ / KARAR DESTEK","TengriContent.kicker.5":"TENGRİ AI","TengriContent.title.6":"Birden fazla sistem. Ortak bir karar resmi.","TengriContent.lead.7":"Tengri AI; hava savunma ağları, insansız sistemler, roket teknolojileri ve haberleşme altyapılarının birlikte ele alındığı çok katmanlı bir yapay zekâ ve karar destek vizyonudur.","TengriContent.image.8":"tengri-network.svg","TengriContent.text.9":"AĞ MERKEZLİ YAPAY ZEKÂ","TengriContent.text.10":"Veriyi anlamlandıran, sistemleri buluşturan yaklaşım.","TengriContent.text.11":"Tengri AI’ın odağında sensör ve platform verilerinden durumsal farkındalık oluşturulması, tehditlerin değerlendirilmesi ve karar süreçlerinin desteklenmesi yer alır. Amaç, birbirinden ayrı sistemleri daha bütünlüklü bir bilgi ve koordinasyon yapısı içinde değerlendirmektir.","TengriContent.text.12":"Tasarımın temelinde çoklu kaynak verisi, tahmine dayalı analiz ve bağlantılı sistem mimarileri bulunur.","TengriContent.kicker.13":"TANITIMDAKİ TEKNOLOJİ BAŞLIKLARI","TengriContent.title.14":"Algılama. Değerlendirme. Koordinasyon.","TengriContent.lead.15":"Tengri AI yaklaşımının temelini oluşturan teknoloji başlıkları.","cards.technology.25.title":"Veri & Sensör Birleşimi","cards.technology.25.description":"Farklı kaynaklardan elde edilen bilgilerin ortak bir durum görünümüne katkıda bulunması.","cards.technology.25.href":"sensor-fuzyonu.html","cards.technology.26.title":"Çoklu Hedef Takibi","cards.technology.26.description":"Birden fazla hava unsuruna ilişkin iz bilgilerinin birlikte değerlendirilmesi fikri.","cards.technology.26.href":"hava-savunma-aglari.html","cards.technology.27.title":"Tehdit Analizi","cards.technology.27.description":"Yapay zekâ destekli değerlendirme ve önceliklendirme süreçlerinin karar desteğindeki rolü.","cards.technology.27.href":"hava-savunma-aglari.html","cards.technology.28.title":"Öngörüsel Değerlendirme","cards.technology.28.description":"Gelişen durumların ve olası senaryoların önceden değerlendirilmesine yönelik yaklaşım.","cards.technology.28.href":"otonom-sistemler.html","cards.technology.29.title":"Komuta & Kontrol","cards.technology.29.description":"Bağlı unsurlardan alınan bilgilerin ortak bir karar ve koordinasyon çerçevesinde incelenmesi.","cards.technology.29.href":"hava-savunma-aglari.html","cards.technology.30.title":"Ağ Tabanlı Entegrasyon","cards.technology.30.description":"Farklı platform ve sistemlerin haberleşme ve veri paylaşımı yoluyla birlikte ele alınması.","cards.technology.30.href":"ileri-haberlesme.html","TengriContent.kicker.16":"ENTEGRE SİSTEM YAKLAŞIMI","TengriContent.title.17":"Bağlantılı bir teknoloji ekosistemi.","TengriContent.lead.18":"Tengri AI’ın kamuya açık vizyonunda farklı sistem ailelerinin ortak bir yapıda değerlendirilmesi hedefleniyor.","TengriContent.title.19":"İnsansız Hava Platformları","TengriContent.description.20":"Hava araçları ve uçuş sistemlerinin sağladığı verilerin daha geniş bir durum değerlendirmesine dahil edilmesi yaklaşımı.","TengriContent.title.21":"Savunma Alt Sistemleri","TengriContent.description.22":"Hava savunma ve roket sistemleri gibi farklı bileşenler arasında ortak bilgi ve koordinasyon gereksinimi.","TengriContent.title.23":"Haberleşme Altyapısı","TengriContent.description.24":"Bağlantılı birimler arasında bilgi aktarımı, veri bütünlüğü ve sistemler arası iletişim kavramları.","TengriContent.title.25":"Kritik alanlar için durumsal farkındalık.","TengriContent.kicker.26":"VİZYON & KARAR DESTEK","TengriContent.description.27":"Kritik altyapılar, stratejik bölgeler ve olası tehdit senaryoları için durumsal farkındalık, önceliklendirme ve öngörüye dayalı değerlendirme bu teknoloji vizyonunun kullanım alanları arasında yer alır. Bunlar mevcut operasyonel yetenek olarak değil, hedeflenen çalışma alanları olarak ele alınmaktadır.","TengriContent.image.28":"research-lab.svg","TengriContent.kicker.29":"İLİŞKİLİ TEKNOLOJİLER","TengriContent.title.30":"Tengri AI ve sistem mühendisliği.","TengriContent.lead.31":"Gömülü yazılım, sensör füzyonu, otonomi ve haberleşme; ağ bağlantılı yapay zekâ yaklaşımlarını tamamlayan mühendislik alanlarıdır."}}'::jsonb) on conflict(kind,slug) do update set body=excluded.body where cms_documents.revision=1 and not(cms_documents.body ? 'fields');
insert into public.cms_documents(kind,slug,body) values('page','ucus-kontrol-paylasimi','{"title":"Uçuş Kontrolcüsü Paylaşımı | İstikbal Aerospace","summary":"Yapay zekâ ile entegre uçuş kontrolcüsü hakkında kamuya açık teknoloji tanıtımı.","paragraphs":[],"date":null,"source":null,"stage":null,"fields":{"news.article.heroTitle":"Uçuş Kontrolcüsü","news.article.heroDescription":"Yapay zekâ ile entegre yeni nesil uçuş kontrolcüsü tanıtımı.","news.image":"platform-systems.svg","news.article.breadcrumb":"HABERLER / UÇUŞ KONTROLCÜSÜ","news.article.eyebrow":"KAMUYA AÇIK TEKNOLOJİ TANITIMI","news.article.heading":"Yapay zekâ ile entegre uçuş kontrolü.","news.article.intro":"İstikbal Aerospace’in LinkedIn üzerinden paylaşılan yeni nesil uçuş kontrolcüsü tanıtımında, yapay zekâ destekli kontrol algoritmaları ve uçuş sistemlerinde güvenlik ile verimlilik hedefleri öne çıkarılıyor.","news.article.sectionHeading":"Mühendislik yaklaşımı","news.article.sectionBody":"Uçuş elektroniği; gömülü işlem birimleri, sensör verileri, kontrol yazılımı ve geri bildirim mekanizmalarını bir araya getirir. Bu tanıtım, doğrulanmış test sonuçları veya sertifikasyon bilgisi içermediğinden performans değerleri yayımlanmamaktadır.","news.article.note":"Şirketin kamuya açık paylaşımı LinkedIn faaliyetinde yer almakta; tam yayın tarihi ve ayrıntılı teknik dokümanları henüz doğrulanmamıştır."}}'::jsonb) on conflict(kind,slug) do update set body=excluded.body where cms_documents.revision=1 and not(cms_documents.body ? 'fields');
insert into public.cms_documents(kind,slug,body) values('page','ucus-mimarileri','{"title":"Gömülü Uçuş Mimarileri | İstikbal Aerospace","summary":"Uçuş elektroniği, gömülü yazılım ve sistem entegrasyonunun mühendislik temelleri.","paragraphs":[],"date":null,"source":null,"stage":null,"fields":{"platformFocus.flightArch.title":"Gömülü Uçuş Mimarileri","platformFocus.flightArch.description":"Donanım ve yazılımın birlikte geliştirildiği uçuş sistemleri.","platformFocus.flightArch.image":"platform-systems.svg","platformFocus.flightArch.kicker":"GÖMÜLÜ UÇUŞ MİMARİSİ","FocusContent.text.8":"SİSTEM ODAĞI","FocusContent.text.9":"Birlikte çalışan teknolojiler.","platformFocus.flightArch.intro":"Uçuş sistemlerinde gömülü mimari; kart tasarımı, işlem birimi, çevre birimleri, veri arabirimleri ve kontrol yazılımının birlikte değerlendirilmesini gerektirir.","FocusContent.kicker.10":"MÜHENDİSLİK KATMANLARI","FocusContent.title.11":"Sistem bütünlüğü.","FocusContent.lead.12":"Havacılık çalışmalarında birbirini tamamlayan temel mühendislik başlıkları.","platformFocus.flightArch.modules.0.0":"Elektronik tasarım","platformFocus.flightArch.modules.0.1":"PCB ve temel elektronik bileşenlerin sistem ihtiyaçlarına göre ele alınması.","platformFocus.flightArch.modules.1.0":"Gömülü yazılım","platformFocus.flightArch.modules.1.1":"Donanım kaynakları, zamanlama ve sistem davranışı.","platformFocus.flightArch.modules.2.0":"Entegrasyon","platformFocus.flightArch.modules.2.1":"Bileşenlerin bütünleşik yapı içinde çalışmasının değerlendirilmesi.","FocusContent.text.13":"Otonom sistemler, gömülü donanım ve sensör füzyonu bu mimarilerle ilişkili mühendislik disiplinleridir."}}'::jsonb) on conflict(kind,slug) do update set body=excluded.body where cms_documents.revision=1 and not(cms_documents.body ? 'fields');
insert into public.cms_versions(document_id,revision,body) select id,revision,body from public.cms_documents where kind='page' on conflict do nothing;
